def generate(self, request: LLMRequest) -> LLMResponse:
    self.requests.append(request)
    if self.error:
        raise self.error
    text = self.texts[min(len(self.requests) - 1, len(self.texts) - 1)] if self.texts else self.text
    return LLMResponse(
        text,
        "fake-model",
        "fake-provider",
        finish_reason=self.finish_reason,
    )

